def ocr_suggests_eskay_medicals_marg_table(ocr_text: str = "", vendor: str = "") -> bool:
    """ESKAY MEDICALS ENTERPRISES MARG table: Mfr Qty Free Pack ... M.R.P Rate Dis."""
